import {TOPICS,PACKS,topicById} from './curriculum.js';
import {freshMemory,validMemory,runAgent,gradeQuiz,retrieve,mastery,exportMarkdown} from './agent.js';
const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let storageOk=true;
function load(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{storageOk=false;return fallback;}}
let memory=validMemory(load('studypilot.memory',freshMemory()));
let goal=load('studypilot.goal',{text:'Prepare the AI fundamentals pack for my review',pack:'ai',days:3,minutes:60});
let notes=load('studypilot.notes','');if(typeof notes!=='string')notes='';
let result;try{result=runAgent(goal,memory,notes);}catch{goal={text:'Prepare the AI fundamentals pack for my review',pack:'ai',days:3,minutes:60};result=runAgent(goal,memory,notes);}
let view='plan',quizTopic=result.plan.days.flatMap(d=>d.tasks)[0]?.topicId||'agents',quizResult=null,search='',coachAvailable=false,coachBusy=false;
function save(key,value){try{localStorage.setItem(key,JSON.stringify(value));}catch{storageOk=false;toast('Browser storage is unavailable. Export your plan before closing.');}}
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3800);}
const labels={plan:'Study plan',practice:'Practice',knowledge:'Knowledge base',progress:'My progress',schema:'How the agent works'};
const actions={inspect_goal:'Understand the goal',retrieve_lessons:'Find useful knowledge',schedule_sessions:'Choose & schedule actions',check_constraints:'Check the plan',finish:'Ready for your feedback',observe_feedback:'Learn from your result'};
function summary(){const attempted=Object.keys(memory.topics).filter(id=>topicById(id)?.pack===goal.pack),weak=attempted.filter(id=>mastery(memory,id)<.8);return {attempted,weak};}
function render(){
 document.querySelectorAll('[data-view]').forEach(el=>{el.classList.toggle('active',el.dataset.view===view);if(el.dataset.view===view)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});
 $('#breadcrumb').textContent=labels[view];
 const titles={plan:'Make room for your<br><em>next breakthrough.</em>',practice:'A small check.<br><em>A smarter next step.</em>',knowledge:'Good knowledge.<br><em>Always within reach.</em>',progress:'Look how far<br><em>you’re coming along.</em>',schema:'Meet the loop<br><em>behind your next step.</em>'};
 const descriptions={plan:'One goal. A clear plan. A next step that learns from you.',practice:'Try three questions. Your agent will use the result to replan.',knowledge:'Browse the lessons or search your own notes alongside them.',progress:'Your practice history helps the agent choose what comes next.',schema:'A transparent agent: observe, plan, act, check, and adapt.'};
 $('#page-title').innerHTML=titles[view];$('#page-description').textContent=descriptions[view];
 $('#view-root').innerHTML=(!storageOk?'<p class="storage-warning">Browser storage is unavailable. Progress lasts for this open session; export it to keep a copy.</p>':'')+({plan:planView,practice:practiceView,knowledge:knowledgeView,progress:progressView,schema:schemaView}[view])();
}
function planView(){const p=result.plan,s=summary();return `
 <div class="goal-grid"><form class="card goal-card" id="goal-form"><div class="card-top"><span class="square-icon">◎</span><div><h2>What would you like to learn?</h2><p>Set the direction. Let your agent find the next steps.</p></div></div>
 <label for="goal-text">MY STUDY GOAL</label><textarea id="goal-text" name="text" maxlength="600" minlength="3" required>${esc(goal.text)}</textarea>
 <div class="input-row"><div><label for="pack">Subject</label><select id="pack" name="pack">${PACKS.map(x=>`<option value="${x.id}" ${x.id===goal.pack?'selected':''}>${esc(x.title)}</option>`).join('')}</select></div><div><label for="days">Study days</label><input id="days" name="days" type="number" min="1" max="30" step="1" value="${goal.days}" required></div><div><label for="minutes">Minutes / day</label><input id="minutes" name="minutes" type="number" min="15" max="180" step="1" value="${goal.minutes}" required></div></div>
 <div class="goal-actions"><small>Your plan adapts after each quiz. No account or API key required.</small><button class="button" type="submit">Build my plan <span>↗</span></button></div><p class="error" id="goal-error" role="alert"></p></form>
 <aside class="card agent-summary"><span class="agent-badge">✳ &nbsp; YOUR AGENT IS ON IT</span><h2>${s.weak.length?'Let’s strengthen<br>the foundations.':'A clear path.<br>At your own pace.'}</h2><p>${s.weak.length?`${s.weak.length} topic(s) need reinforcement. Your quiz results now shape your next plan.`:'Your agent connects the basics, respects your time, and makes space for practice.'}</p><div class="summary-stats"><div><strong>${p.days.length}<span>study days</span></strong></div><div><strong>${p.used}<span>planned minutes</span></strong></div><div><strong>${p.audit?.scheduled??new Set(p.days.flatMap(d=>d.tasks.map(t=>t.topicId))).size}<span>topics</span></strong></div></div></aside></div>
 <div class="section-title"><div><h2>Your learning path <span class="tag">${s.attempted.length?'Adapted to you':'Starter plan'}</span></h2><p>${esc(PACKS.find(x=>x.id===goal.pack).title)} · ${p.used} of ${p.capacity} minutes allocated</p></div><button class="button secondary small" data-action="export">↓ Export plan</button></div>
 <div class="plan-layout"><div class="plan-days">${p.days.map(d=>`<article class="card day-card"><div class="day-head"><span class="day-number">Day ${String(d.day).padStart(2,'0')} <span>${d.day===1?'Start here':'Keep the momentum'}</span></span><span class="day-time">${d.used} / ${goal.minutes} min</span></div>${d.tasks.map(t=>`<div class="task ${memory.completed.includes(t.id)?'done':''}"><input type="checkbox" data-task="${t.id}" ${memory.completed.includes(t.id)?'checked':''} aria-label="Mark ${esc(t.title)} part ${t.part} complete"><div><div class="task-title">${esc(t.title)}${t.part>1?' · continued':''}</div><div class="task-meta">${t.mode==='review'?'Review & recall':'Learn & practise'} · ${t.minutes} min · ${esc(t.reason)}</div></div><button class="task-open" data-lesson="${t.topicId}">Open ↗</button></div>`).join('')||'<div class="empty">Open time for extra practice or a well-earned break.</div>'}</article>`).join('')}<div class="note ${p.deferred.length?'warning':''}">${esc(p.note)}${p.deferred.length?`<br>Deferred: ${p.deferred.map(id=>esc(topicById(id).title)).join(', ')}.`:''}<br>Checking off a session records completion; only quizzes update knowledge estimates.</div></div><aside class="card trace-card"><div class="trace-header"><span class="live-dot"></span> Inside your agent</div><p class="trace-subtitle">Actual actions from this run · ${result.trace.length} steps<br>Local symbolic policy · no language model</p>${result.trace.map(t=>`<div class="trace-step"><strong>${esc(actions[t.action]||t.action)}</strong><p>${esc(t.observation)}</p></div>`).join('')}</aside></div>`;}
function practiceView(){const t=topicById(quizTopic),r=quizResult;return `<div class="card quiz-card"><div class="quiz-top"><div><h2>A quick knowledge check</h2><p class="trace-subtitle">Original practice questions · 3 per topic</p></div><label class="input-label" for="quiz-topic">Choose a topic<select id="quiz-topic">${TOPICS.map(x=>`<option value="${x.id}" ${x.id===quizTopic?'selected':''}>${esc(x.title)}</option>`).join('')}</select></label></div><p>Take a breath and try it from memory. ${r?'Your result has been saved and the study plan has been updated.':'Your answers help the agent decide what needs more attention.'}</p>
 <form id="quiz-form">${t.questions.map((q,i)=>`<fieldset class="question"><legend>${i+1}. ${esc(q.prompt)}</legend>${q.options.map((o,j)=>`<label class="answer ${r?(j===q.answer?'correct':j===r.detail[i].selected?'wrong':''):''}"><input type="radio" name="q${i}" value="${j}" ${r?'disabled':''} ${r&&r.detail[i].selected===j?'checked':''} required><span>${esc(o)}</span></label>`).join('')}${r?`<div class="explanation">${r.detail[i].correct?'✓ Correct.':'↗ Let’s revisit this.'} ${esc(q.explanation)}</div>`:''}</fieldset>`).join('')}
 ${r?`<div class="quiz-result"><h3>${r.correct} of ${r.total} correct · ${Math.round(r.score*100)}%</h3><p>${r.score>=.8?'Good work. The agent can make room for other topics.':'You have a useful next step: revisit this lesson, then try again.'} Your knowledge estimate is now ${Math.round(r.mastery*100)}%. This is a small practice check, not an exam prediction.</p></div><div class="button-row"><button type="button" class="button" data-view="plan">See my updated plan ↗</button><button type="button" class="button secondary" data-action="retry-quiz">Try again</button></div>`:`<div class="button-row"><button type="submit" class="button">Check & adapt my plan ↗</button><button type="button" class="button secondary" data-lesson="${t.id}">Read the lesson</button></div>`}<p class="error" id="quiz-error" role="alert"></p></form></div>`;}
function knowledgeView(){const hits=search?retrieve(search,null,notes):null;const topics=hits?hits.filter(h=>h.id!=='personal-notes').map(h=>topicById(h.id)):TOPICS;return `<form class="knowledge-toolbar" id="search-form"><label class="input-label" for="search-input" style="position:absolute;left:-10000px">Search lessons and notes</label><input id="search-input" type="text" placeholder="Search a concept: pooling, chip ratio, precision…" value="${esc(search)}" maxlength="200"><button class="button" type="submit">Search</button>${search?'<button class="button secondary" type="button" data-action="clear-search">Clear</button>':''}</form>
 ${search?`<p class="trace-subtitle">${hits.length} matching source(s). Keyword retrieval returns excerpts; it does not invent answers.</p>`:''}<div class="grid-2">${topics.map(t=>`<article class="card lesson-card"><span class="tag">${t.pack==='ai'?'AI FUNDAMENTALS':'MANUFACTURING'}</span><h3>${esc(t.title)}</h3><p>${esc(t.summary.slice(0,180))}…</p><div class="button-row"><button class="button secondary small" data-lesson="${t.id}">Read lesson ↗</button><button class="text-button" data-quiz="${t.id}">Practice · 3 questions</button></div></article>`).join('')}${hits?.some(h=>h.id==='personal-notes')?`<article class="card lesson-card"><span class="tag">YOUR NOTES</span><h3>Notes matching your search</h3><p>${esc(notes.slice(0,1400))}</p><small class="trace-subtitle">User-provided material; not independently verified.</small></article>`:''}</div>${search&&!hits.length?'<div class="empty">No match yet. Try a specific term from a lesson or your notes.</div>':''}
 <form class="card notes-card" id="notes-form"><h2>Bring your own notes</h2><p>Paste plain-text notes to make them searchable alongside the built-in lessons. Notes do not add new quiz questions or change the built-in topic syllabus. They stay in this browser unless you use the optional AI coach.</p><label class="input-label" for="notes">MY NOTES · UP TO 12,000 CHARACTERS</label><textarea id="notes" maxlength="12000" placeholder="Paste a useful explanation, a class note, or a formula…">${esc(notes)}</textarea><button class="button secondary" type="submit">Save notes</button></form>
 <section class="card coach-card"><h2>Optional AI coach</h2><p>${coachAvailable?'A server-side language model can choose tools to search lessons, inspect your progress and propose a plan. Your question, study goal, scores and saved notes will be sent to OpenAI when you ask.':'This hosted workspace uses the complete local agent. The source code also includes an optional server-side language-model coach. Run it with your own API key and model to enable natural-language help.'}</p>${coachAvailable?'<form id="coach-form" class="coach-form"><input id="coach-message" type="text" maxlength="1000" minlength="3" required placeholder="What should I study next, and why?" aria-label="Question for AI coach"><button class="button" type="submit">Ask AI coach ↗</button></form><div id="coach-output" class="coach-output" role="status"></div>':'<span class="tag">API key not configured · local agent stays available</span>'}</section>`;}
function progressView(){const entries=Object.entries(memory.topics),avg=entries.length?entries.reduce((s,[,t])=>s+t.mastery,0)/entries.length:null;return `<div class="progress-metrics"><div class="card metric"><span>QUIZZES COMPLETED</span><strong>${memory.attempts.length}</strong><small>Saved practice attempts</small></div><div class="card metric"><span>KNOWLEDGE ESTIMATE</span><strong>${avg===null?'—':Math.round(avg*100)+'%'}</strong><small>Across tested topics only</small></div><div class="card metric"><span>SESSIONS CHECKED OFF</span><strong>${memory.completed.length}</strong><small>Self-reported completion</small></div></div><section class="card progress-list"><h2>Your topic map</h2><p class="trace-subtitle">Estimates update after quizzes. Untested topics have a 35% planning prior; this is not a measured score.</p>${TOPICS.map(t=>`<div class="progress-row"><span>${esc(t.title)}</span><div class="bar" role="meter" aria-label="${esc(t.title)} knowledge estimate" aria-valuenow="${memory.topics[t.id]?Math.round(mastery(memory,t.id)*100):0}" aria-valuemin="0" aria-valuemax="100" aria-valuetext="${memory.topics[t.id]?Math.round(mastery(memory,t.id)*100)+' percent':'Not tested'}"><i style="width:${memory.topics[t.id]?Math.round(mastery(memory,t.id)*100):0}%"></i></div><span>${memory.topics[t.id]?Math.round(mastery(memory,t.id)*100)+'%':'—'}</span></div>`).join('')}</section><section class="card history"><h2>Practice history</h2>${memory.attempts.length?memory.attempts.slice().reverse().slice(0,15).map(a=>`<div class="history-row"><span>${esc(topicById(a.topicId)?.title||a.topicId)} · ${a.correct}/${a.total}</span><span>${esc(new Date(a.at).toLocaleDateString())}</span></div>`).join(''):'<div class="empty">Your first quiz is the beginning of your learning history.<br>Head to Practice when you’re ready.</div>'}</section><div class="section-title"><button class="button secondary small" data-action="export-memory">↓ Export progress</button><button class="text-button" data-action="reset">Reset learning history</button></div>`;}
function schemaView(){return `<section class="card schema-card"><span class="tag">OPTION I · AGENTIC AGENT PROJECT</span><h2 style="margin-top:17px">StudyPilot: a goal-driven adaptive study agent</h2><p>The default controller is a classical symbolic AI agent. It uses rules, a priority heuristic, prerequisite planning, executable tools and persistent feedback. It does not call a language model or train a neural network. An optional LLM tool-calling coach is included in the repository.</p><div class="schema-flow"><div class="schema-node"><strong>01 · Observe</strong><small>Goal, time budget, quiz results, saved memory</small></div><div class="schema-node"><strong>02 · Plan</strong><small>Select topics, add prerequisites, rank knowledge gaps</small></div><div class="schema-node"><strong>03 · Act</strong><small>Retrieve lessons, schedule sessions, assess answers</small></div><div class="schema-node"><strong>04 · Adapt</strong><small>Check constraints, update estimates, replan from feedback ↶</small></div></div><h3>Why this is an agent</h3><p>The learner gives a goal and constraints. A bounded controller selects tools using the current state, produces a checked plan and waits for external feedback. A quiz changes the memory used by the next planning run. The learner still does the studying; the agent automates study management.</p><h3>The decision rule</h3><p><code>priority = 3 × (1 − estimate) + 2 × goal_match + overdue_bonus</code></p><p>Prerequisites come first. A topic with a stronger knowledge gap receives higher priority. Reviews at least three days old get a 0.5 bonus. Capacity limits can defer a topic; the agent reports that openly.</p><table class="schema-table"><thead><tr><th>Component</th><th>Implementation</th><th>Responsibility</th></tr></thead><tbody><tr><td>Interface</td><td>HTML, CSS, JavaScript</td><td>Goal entry, lessons, practice, progress, export</td></tr><tr><td>Controller & tools</td><td>agent.js</td><td>State-based action selection, retrieval, scheduling, audit, grading</td></tr><tr><td>Knowledge</td><td>curriculum.js + notes</td><td>12 lessons, 36 original questions, prerequisite graph</td></tr><tr><td>Memory</td><td>Browser localStorage</td><td>Topic estimates, quiz attempts, completed sessions</td></tr><tr><td>Optional LLM</td><td>Node server + OpenAI Responses API</td><td>Select allowed tools and explain their outputs; key stays on server</td></tr></tbody></table><h3>A short demonstration</h3><ol><li>Create a plan for “CNN and pooling” with a limited daily budget.</li><li>Observe that machine-learning and neural-network prerequisites are included.</li><li>Take a quiz and deliberately miss an answer.</li><li>Open the revised plan and progress page to show the feedback loop.</li><li>Export the plan and point to the action trace.</li></ol><h3>Scope and limitations</h3><p>This is a teaching prototype. The heuristic estimates are not calibrated measurements of ability. The local agent covers two small built-in packs, not a complete exam syllabus. Keyword retrieval may miss synonyms. Browser memory is device-specific. A faculty member must decide whether this symbolic implementation meets their definition of the 10-mark category; use the LLM extension if their rubric specifically requires a language model.</p><div class="button-row"><a class="button" href="./development-schema.pdf" target="_blank" rel="noopener">Open development schema ↗</a><a class="button secondary" href="https://github.com/kritee-saxena/AI_AGENT" target="_blank" rel="noopener">View repository ↗</a></div></section>`;}
function openLesson(id){const t=topicById(id);if(!t)return;$('#lesson-content').innerHTML=`<span class="tag">${t.pack==='ai'?'AI FUNDAMENTALS':'MANUFACTURING'} · ${t.minutes} MIN</span><h2>${esc(t.title)}</h2><p>${esc(t.summary)}</p><h3>A SIMPLE EXAMPLE</h3><p class="lesson-example">${esc(t.example)}</p>${t.prerequisites.length?`<p class="trace-subtitle">Helpful first: ${t.prerequisites.map(p=>esc(topicById(p).title)).join(', ')}.</p>`:''}<button class="button" data-quiz="${t.id}">Ready? Try 3 questions ↗</button>`;$('#lesson-dialog').showModal();}
function download(name,content,type='text/plain'){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('click',e=>{
 const nav=e.target.closest('[data-view]');if(nav){view=nav.dataset.view;render();$('#main').scrollIntoView({behavior:'smooth',block:'start'});return;}
 const lesson=e.target.closest('[data-lesson]');if(lesson){openLesson(lesson.dataset.lesson);return;}
 const quiz=e.target.closest('[data-quiz]');if(quiz){quizTopic=quiz.dataset.quiz;quizResult=null;view='practice';$('#lesson-dialog').close();render();return;}
 if(e.target.closest('.close-dialog')){$('#lesson-dialog').close();return;}
 const act=e.target.closest('[data-action]')?.dataset.action;
 if(act==='export')download('StudyPilot-plan.md',exportMarkdown(result,memory),'text/markdown');
 if(act==='export-memory')download('StudyPilot-progress.json',JSON.stringify(memory,null,2),'application/json');
 if(act==='clear-search'){search='';render();}
 if(act==='retry-quiz'){quizResult=null;render();}
 if(act==='reset')$('#reset-dialog').showModal();
 if(act==='cancel-reset')$('#reset-dialog').close();
 if(act==='confirm-reset'){memory=freshMemory();save('studypilot.memory',memory);result=runAgent(goal,memory,notes);quizResult=null;$('#reset-dialog').close();render();toast('Learning history reset.');}
});
document.addEventListener('change',e=>{
 if(e.target.id==='quiz-topic'){quizTopic=e.target.value;quizResult=null;render();}
 if(e.target.dataset.task){const id=e.target.dataset.task;memory.completed=e.target.checked?[...new Set([...memory.completed,id])]:memory.completed.filter(x=>x!==id);save('studypilot.memory',memory);e.target.closest('.task').classList.toggle('done',e.target.checked);}
});
document.addEventListener('submit',async e=>{
 if(e.target.id==='goal-form'){e.preventDefault();const f=new FormData(e.target);try{const next={text:f.get('text'),pack:f.get('pack'),days:Number(f.get('days')),minutes:Number(f.get('minutes'))};const nextResult=runAgent(next,memory,notes);goal=next;result=nextResult;save('studypilot.goal',goal);render();toast('Your plan is ready. Open the first lesson to begin.');}catch(err){$('#goal-error').textContent=err.message;}}
 if(e.target.id==='quiz-form'){e.preventDefault();if(quizResult)return;try{const f=new FormData(e.target),answers=topicById(quizTopic).questions.map((_,i)=>f.has(`q${i}`)?Number(f.get(`q${i}`)):null);quizResult=gradeQuiz(quizTopic,answers,memory);memory=quizResult.memory;save('studypilot.memory',memory);result=runAgent(goal,memory,notes);result.trace.unshift({step:0,action:'observe_feedback',observation:`${topicById(quizTopic).title}: ${quizResult.correct}/${quizResult.total} correct. Knowledge estimate updated to ${Math.round(quizResult.mastery*100)}%; plan recalculated.`});render();toast('Result saved. Your agent has revised the plan.');}catch(err){$('#quiz-error').textContent=err.message;}}
 if(e.target.id==='search-form'){e.preventDefault();search=$('#search-input').value.trim();render();}
 if(e.target.id==='notes-form'){e.preventDefault();notes=$('#notes').value.slice(0,12000);save('studypilot.notes',notes);toast('Notes saved and ready to search.');}
 if(e.target.id==='coach-form'){e.preventDefault();if(coachBusy)return;coachBusy=true;const output=$('#coach-output'),button=e.target.querySelector('button');button.disabled=true;output.textContent='The coach is choosing tools and checking their results…';try{const response=await fetch('./api/coach',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:$('#coach-message').value,goal,memory,notes})});const data=await response.json();if(!response.ok)throw new Error(data.error||'The coach could not complete this request.');output.textContent=data.text+'\n\nTools used: '+data.trace.map(t=>t.name).join(' → ');if(data.plan){result=data.plan;toast('The AI coach proposed a new plan. See Study plan.');}}catch(err){output.textContent=err.message;}finally{coachBusy=false;button.disabled=false;}}
});
render();
fetch('./api/config').then(r=>r.ok?r.json():null).then(c=>{coachAvailable=c?.coachAvailable===true;if(view==='knowledge')render();}).catch(()=>{});
